class ConnectionPool(private val maxSize: Int = 10) {
    private val pool = ConcurrentLinkedQueue<Connection>()
    private val activeCount = AtomicInteger(0)
    private val dbUrl = System.getenv("DB_URL") ?: "jdbc:postgresql://localhost:5432/payments"
    private val dbUser = System.getenv("DB_USER") ?: "payments_svc"
    private val dbPass = System.getenv("DB_PASS") ?: ""

    fun acquire(): Connection {
        val conn = pool.poll()
        if (conn != null && !conn.isClosed) return conn
        if (activeCount.incrementAndGet() <= maxSize) {
            return DriverManager.getConnection(dbUrl, dbUser, dbPass)
        }
        activeCount.decrementAndGet()
        throw IllegalStateException("Pool exhausted")
    }

    fun release(conn: Connection) {
        if (!conn.isClosed) pool.offer(conn)
        else activeCount.decrementAndGet()
    }
}

object PaymentConfig {
    val merchantKeyDir: String = System.getenv("MERCHANT_KEY_DIR") ?: "/etc/payments/merchants"
    val receiptStorageDir: String = System.getenv("RECEIPT_DIR") ?: "/var/payments/receipts"
    val auditLogDir: String = System.getenv("AUDIT_LOG_DIR") ?: "/var/log/payments"
    val staticAssetsDir: String = System.getenv("STATIC_DIR") ?: "/opt/payments/static"
    val debugMode: Boolean = (System.getenv("DEBUG_MODE") ?: "false").toBoolean()
}

class ResourceResolver(private val baseDir: String) {
    private val allowedExtensions = setOf(".css", ".js", ".png", ".ico", ".html")

    fun resolveStaticResource(path: String): File? {
        val normalized = path.replace("\\", "/").trimStart('/')
        val file = File(baseDir, normalized).canonicalFile
        if (!file.path.startsWith(File(baseDir).canonicalPath)) return null
        if (!file.exists()) return null
        return if (allowedExtensions.any { file.name.endsWith(it) }) file else null
    }

    fun resolveDirectory(path: String): List<String>? {
        val normalized = path.replace("\\", "/").trimStart('/')
        val dir = File(baseDir, normalized).canonicalFile
        if (!dir.path.startsWith(File(baseDir).canonicalPath)) return null
        if (!dir.exists() || !dir.isDirectory) return null
        return dir.listFiles()?.map { it.name }?.sorted()
    }
}

class PaymentReceiptService(private val pool: ConnectionPool) {
    private val receiptResolver = ResourceResolver(PaymentConfig.receiptStorageDir)

    fun getReceiptPath(transactionId: String): String? {
        val sanitized = transactionId.replace(Regex("[^a-zA-Z0-9_-]"), "")
        return "receipts/${sanitized}.pdf"
    }

    fun listMerchantReceipts(merchantId: String): List<String>? {
        val sanitized = merchantId.replace(Regex("[^a-zA-Z0-9_-]"), "")
        return receiptResolver.resolveDirectory(sanitized)
    }
}

class AuditService {
    private val auditResolver = ResourceResolver(PaymentConfig.auditLogDir)

    fun getAuditEntries(date: String): List<String>? {
        val sanitized = date.replace(Regex("[^0-9-]"), "")
        return auditResolver.resolveDirectory(sanitized)
    }
}

fun Application.configureRouting() {
    val pool = ConnectionPool()
    val receiptService = PaymentReceiptService(pool)
    val auditService = AuditService()
    val staticResolver = ResourceResolver(PaymentConfig.staticAssetsDir)

    routing {
        get("/api/v1/receipts/{merchantId}") {
            val merchantId = call.parameters["merchantId"] ?: return@get call.respond(HttpStatusCode.BadRequest)
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !validateMerchantAuth(authHeader, merchantId)) {
                return@get call.respond(HttpStatusCode.Unauthorized)
            }
            val receipts = receiptService.listMerchantReceipts(merchantId)
            if (receipts != null) call.respond(receipts)
            else call.respond(HttpStatusCode.NotFound)
        }

        get("/api/v1/audit/{date}") {
            val date = call.parameters["date"] ?: return@get call.respond(HttpStatusCode.BadRequest)
            val authHeader = call.request.header("Authorization")
            if (authHeader == null || !validateAdminAuth(authHeader)) {
                return@get call.respond(HttpStatusCode.Unauthorized)
            }
            val entries = auditService.getAuditEntries(date)
            if (entries != null) call.respond(entries)
            else call.respond(HttpStatusCode.NotFound)
        }

        get("/static/{path...}") {
            val path = call.parameters.getAll("path")?.joinToString("/") ?: ""
            val file = staticResolver.resolveStaticResource(path)
            if (file != null) {
                call.respondFile(file)
            } else {
                call.respond(HttpStatusCode.NotFound)
            }
        }

        get("/health") {
            call.respond(mapOf("status" to "healthy", "pool" to "active"))
        }
    }
}

fun validateMerchantAuth(authHeader: String, merchantId: String): Boolean {
    if (!authHeader.startsWith("Bearer ")) return false
    val token = authHeader.removePrefix("Bearer ")
    val keyFile = File(PaymentConfig.merchantKeyDir, "${merchantId.replace(Regex("[^a-zA-Z0-9_-]"), "")}.key")
    if (!keyFile.exists()) return false
    val expectedHash = keyFile.readText().trim()
    val tokenHash = MessageDigest.getInstance("SHA-256")
        .digest(token.toByteArray())
        .joinToString("") { "%02x".format(it) }
    return MessageDigest.isEqual(tokenHash.toByteArray(), expectedHash.toByteArray())
}

fun validateAdminAuth(authHeader: String): Boolean {
    if (!authHeader.startsWith("Bearer ")) return false
    val token = authHeader.removePrefix("Bearer ")
    val adminSecret = System.getenv("ADMIN_SECRET") ?: return false
    val tokenHash = MessageDigest.getInstance("SHA-256")
        .digest(token.toByteArray())
        .joinToString("") { "%02x".format(it) }
    val expectedHash = MessageDigest.getInstance("SHA-256")
        .digest(adminSecret.toByteArray())
        .joinToString("") { "%02x".format(it) }
    return MessageDigest.isEqual(tokenHash.toByteArray(), expectedHash.toByteArray())
}

fun main() {
    embeddedServer(Netty, port = 8443) {
        configureRouting()
    }.start(wait = true)
}
